<?php
require __DIR__ . '/../lib/bootstrap.php';$user=auth_user();$d=input();if($_SERVER['REQUEST_METHOD']!=='POST')fail('Method not allowed',405);$chat=(int)($d['chat_id']??0);$q=trim((string)($d['question']??''));$opts=$d['options']??[];if($q===''||!is_array($opts)||count($opts)<2)fail('Question and at least two options required');$m=db()->prepare('SELECT 1 FROM chat_members WHERE chat_id=? AND user_id=? AND status="active"');$m->execute([$chat,$user['id']]);if(!$m->fetch())fail('Not a member',403);$pdo=db();$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO polls(chat_id,creator_id,question,multiple_choice,anonymous,created_at) VALUES(?,?,?,?,?,UTC_TIMESTAMP())')->execute([$chat,$user['id'],$q,!empty($d['multiple_choice']),!empty($d['anonymous'])]);$pid=(int)$pdo->lastInsertId();$st=$pdo->prepare('INSERT INTO poll_options(poll_id,option_text,display_order) VALUES(?,?,?)');foreach(array_values($opts) as $idx=>$o){$o=trim((string)$o);if($o!=='')$st->execute([$pid,$o,$idx]);}$pdo->commit();out(['poll_id'=>$pid],201);}catch(Throwable $e){$pdo->rollBack();fail('Poll creation failed',500);}
